package com.huy.enterprise.company;
import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class CompanyService{private final CompanyRepository repository;public List<CompanyResponse> all(){return repository.findAll().stream().map(CompanyResponse::from).toList();}@Transactional public CompanyResponse create(CompanyRequest r){if(r.taxCode()!=null&&repository.existsByTaxCode(r.taxCode()))throw new ConflictException("Company tax code already exists: "+r.taxCode());Company c=new Company();apply(c,r);return CompanyResponse.from(repository.save(c));}@Transactional public CompanyResponse update(UUID id,CompanyRequest r){Company c=get(id);if(r.taxCode()!=null&&!Objects.equals(c.getTaxCode(),r.taxCode())&&repository.existsByTaxCode(r.taxCode()))throw new ConflictException("Company tax code already exists: "+r.taxCode());apply(c,r);return CompanyResponse.from(repository.save(c));}private Company get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Company not found: "+id));}private void apply(Company c,CompanyRequest r){c.setName(r.name());c.setTaxCode(r.taxCode());c.setEmail(r.email());c.setPhone(r.phone());c.setAddress(r.address());c.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());}}
